
insert into public.services (slug, title, tagline, summary, overview, icon, offerings, features, benefits, technologies, portfolio_category, sort_order, seo_title, seo_description) values
('website-development','Website Development','Fast, scalable websites engineered to convert.',
 'Business sites, e-commerce stores and custom web apps built for speed, search and growth.',
 'Your website is your hardest-working salesperson. We design and engineer high-performance websites and web applications that load instantly, rank well, and turn visitors into customers — from a focused landing page to a full custom platform with dashboards, payments and integrations.',
 'Code2',
 array['Business Websites','Portfolio Websites','E-commerce Websites','Custom Web Applications','Landing Pages','Website Maintenance'],
 '[{"title":"Performance-first builds","description":"Optimised assets, server rendering and Core Web Vitals tuned from day one."},{"title":"SEO-ready structure","description":"Semantic markup, metadata, sitemaps and clean URLs so search engines understand you."},{"title":"Content you control","description":"An admin panel to update pages, products and posts without touching code."},{"title":"Secure & scalable","description":"Modern hosting, SSL, backups and an architecture that grows with your traffic."}]'::jsonb,
 array['More enquiries from a site that is built to convert','Faster load times that keep visitors engaged','Lower maintenance costs with a modern, clean codebase','A platform that scales as your business grows'],
 array['React','TypeScript','Next.js','TanStack','Tailwind CSS','Node.js','PostgreSQL','Shopify'],
 'Web Development',1,'Website Development Services | Dev Creative Works','Custom business websites, e-commerce stores and web applications engineered for speed, SEO and conversion.'),
('ai-automation','AI & Automation','Intelligent systems that work while you sleep.',
 'AI chatbots, agents and workflow automation that cut busywork and delight customers.',
 'We help businesses put AI to practical use. From customer-facing chatbots that answer questions around the clock to internal agents that process documents, qualify leads and connect your tools, we design automations that save hours every week and integrate cleanly with the systems you already use.',
 'Bot',
 array['AI Chatbots','AI Agents','Customer Support Automation','Business Process Automation','AI API Integrations','Custom AI Solutions'],
 '[{"title":"Trained on your business","description":"Assistants grounded in your own documents, FAQs and product data."},{"title":"Workflow automation","description":"Connect forms, CRMs, email and spreadsheets so routine work runs itself."},{"title":"Human hand-off","description":"Smart escalation to your team when a conversation needs a person."},{"title":"Secure by design","description":"API keys stay server-side and data access is scoped and logged."}]'::jsonb,
 array['24/7 support without growing headcount','Hours of manual work automated every week','Faster lead response and higher conversion','Measurable ROI with usage and outcome reporting'],
 array['OpenAI','Google Gemini','LangChain','Python','Node.js','Zapier','Make','Vector databases'],
 'AI Solutions',2,'AI Chatbots & Automation | Dev Creative Works','AI chatbots, agents and business process automation that save time and improve customer experience.'),
('ui-ux-design','UI/UX Design','Interfaces people understand at first glance.',
 'Research-led product design for websites, mobile apps and SaaS dashboards.',
 'Great design is invisible — it simply makes things easy. We map user journeys, wireframe flows and craft polished interfaces and design systems for websites, mobile apps and SaaS products, so your users find what they need and your developers ship faster.',
 'PenTool',
 array['Website UI/UX','Mobile App UI/UX','SaaS Dashboard Design','Wireframing','Prototyping','Design Systems'],
 '[{"title":"User research","description":"Interviews, audits and analytics to understand what your users actually need."},{"title":"Wireframes to prototypes","description":"Clickable prototypes to validate ideas before a single line of code."},{"title":"Design systems","description":"Reusable components and tokens that keep every screen consistent."},{"title":"Developer hand-off","description":"Annotated specs and assets that make implementation smooth."}]'::jsonb,
 array['Higher conversion and lower drop-off','Fewer support requests thanks to clearer flows','Faster development with a reusable design system','A product that looks and feels premium'],
 array['Figma','FigJam','Framer','Adobe XD','Protopie','Maze'],
 'UI/UX Design',3,'UI/UX Design Services | Dev Creative Works','Website, mobile app and SaaS dashboard UI/UX design, wireframing, prototyping and design systems.'),
('creative-digital','Creative & Digital Solutions','Brand stories that stop the scroll.',
 'Logos, brand identities, social creatives, video and campaign assets with impact.',
 'A strong brand makes every other channel work harder. We craft logos and identity systems, then bring them to life across social media, print and video — giving you a consistent, recognisable presence that people remember.',
 'Palette',
 array['Logo Design','Branding','Social Media Creatives','Posters and Banners','Video Editing','Digital Marketing Creatives'],
 '[{"title":"Identity systems","description":"Logo, colour, typography and usage guidelines that scale across channels."},{"title":"Campaign creatives","description":"Scroll-stopping social posts, ads, posters and banners on brand."},{"title":"Motion & video","description":"Reels, product videos and edits that tell your story in seconds."},{"title":"Ready-to-use assets","description":"Organised, export-ready files for every platform and format."}]'::jsonb,
 array['A memorable brand that builds trust','Consistent visuals across every channel','More engagement on social and ads','Assets your team can reuse with confidence'],
 array['Adobe Illustrator','Photoshop','After Effects','Premiere Pro','Figma','Canva'],
 'Branding',4,'Branding & Creative Design | Dev Creative Works','Logo design, branding, social media creatives, posters, banners and video editing for growing businesses.');

insert into public.portfolio_items (slug, name, client_name, category, summary, description, challenge, solution, features, technologies, cover_image, screenshots, project_url, completed_on, status, is_featured, sort_order) values
('aurora-estates','Aurora Estates','Aurora Estates (sample)','Web Development',
 'A cinematic property showcase for a luxury real-estate brand.',
 'A high-end marketing website and listings platform presenting premium properties with immersive visuals and a frictionless enquiry flow.',
 'The brand''s old site was slow, hard to update and generated few qualified enquiries from high-value buyers.',
 'We rebuilt the experience around large-format imagery, a filterable listings catalogue and a two-step enquiry form, managed through a simple admin panel.',
 array['Filterable property listings','Virtual tour embeds','Lead capture with CRM sync','CMS-managed content'],
 array['React','TypeScript','Tailwind CSS','PostgreSQL'],
 '/images/work/aurora-estates.jpg', array['/images/work/aurora-estates.jpg'], null, '2026-06-15','Completed',true,1),
('nimbus-ai-assistant','Nimbus AI Assistant','Nimbus Support (sample)','AI Solutions',
 'A 24/7 AI support assistant trained on product documentation.',
 'A conversational assistant that answers customer questions instantly across web and mobile, with smart escalation to human agents.',
 'The support team was overwhelmed by repetitive questions, leading to long response times and frustrated customers.',
 'We trained an assistant on the help centre and order data, added hand-off to live agents and a dashboard to review conversations.',
 array['Knowledge-grounded answers','Human hand-off','Conversation analytics','Multi-channel widget'],
 array['Google Gemini','Node.js','PostgreSQL','React'],
 '/images/work/nimbus-ai-assistant.jpg', array['/images/work/nimbus-ai-assistant.jpg'], null, '2026-08-02','Completed',true,2),
('pulse-analytics','Pulse Analytics','Pulse Labs (sample)','UI/UX Design',
 'A clean, data-dense SaaS dashboard redesign.',
 'End-to-end UX and UI for an analytics product, from research and wireframes to a complete component library.',
 'Users found the existing dashboard cluttered and struggled to find key metrics, hurting retention.',
 'We restructured information architecture, designed a calm dark interface and delivered a design system the team could ship with.',
 array['User research & journey maps','Interactive prototype','Design system with 120+ components','Developer hand-off specs'],
 array['Figma','Protopie','Maze'],
 '/images/work/pulse-analytics.jpg', array['/images/work/pulse-analytics.jpg'], null, '2026-04-20','Completed',true,3),
('ember-coffee','Kōhi Coffee Roasters','Kōhi Coffee (sample)','Branding',
 'A minimal, premium identity for a specialty coffee roaster.',
