insert into public.testimonials (author_name, author_role, company, quote, rating, sort_order) values
('Sample Client','Founder','Aurora Estates','Dev Creative Works rebuilt our website from the ground up. It looks stunning, loads instantly and our enquiries have noticeably improved.',5,1),
('Sample Client','Head of Support','Nimbus Support','The AI assistant now handles the bulk of our routine questions. Our team finally has time for the conversations that matter.',5,2),
('Sample Client','Product Lead','Pulse Labs','Thoughtful, fast and genuinely collaborative. The design system they delivered made our engineering team faster overnight.',5,3);

insert into public.faqs (service_id, question, answer, sort_order) values
(null,'How long does a typical project take?','A focused landing page usually takes 1–2 weeks, a business website 3–6 weeks, and custom web apps or AI solutions 6–12 weeks depending on scope. We share a clear timeline after discovery.',1),
(null,'How do you price your work?','Every project is quoted based on scope after a free consultation. We work with fixed-price milestones for most projects, with an advance payment to begin.',2),
(null,'Do you offer support after launch?','Yes. Every project includes a post-launch support window, and we offer ongoing maintenance plans for updates, security and improvements.',3),
(null,'Can I update the website myself?','Absolutely. We build with an easy admin panel so you can edit content, images and listings without touching any code.',4),
((select id from public.services where slug='website-development'),'Will my website work well on mobile?','Every site we build is mobile-first and tested across phones, tablets and desktops.',1),
((select id from public.services where slug='website-development'),'Do you handle hosting and domains?','Yes — we can set up hosting, domains, SSL and email, or work with your existing provider.',2),
((select id from public.services where slug='ai-automation'),'Is my business data safe with AI tools?','We keep API keys on the server, scope data access tightly and can use providers that do not train on your data.',1),
((select id from public.services where slug='ai-automation'),'Can the chatbot hand off to a real person?','Yes. We configure escalation rules so complex conversations are routed to your team with full context.',2),
((select id from public.services where slug='ui-ux-design'),'Do you also build the designs you create?','Yes — our design and development teams work together, so designs are built exactly as intended.',1),
((select id from public.services where slug='ui-ux-design'),'What do I receive at the end?','Figma files, a clickable prototype, a component library and developer hand-off documentation.',2),
((select id from public.services where slug='creative-digital'),'How many logo concepts will I see?','We typically present three distinct concepts, then refine your favourite through two rounds of revisions.',1),
((select id from public.services where slug='creative-digital'),'Do you create monthly social content?','Yes, we offer monthly creative packages for social posts, reels and ad creatives.',2);

