('why_us', '[{"icon":"Gauge","title":"Built for performance","description":"Fast, accessible, search-friendly products — measured, not guessed."},{"icon":"Sparkles","title":"Design with intent","description":"Every pixel serves a purpose: clarity, trust and conversion."},{"icon":"BrainCircuit","title":"AI-native thinking","description":"We look for where automation can save you time and money."},{"icon":"Handshake","title":"Partners, not vendors","description":"Transparent communication, clear milestones and long-term support."}]'::jsonb),
