('about', '{"who_we_are":"Dev Creative Works is a digital creative and technology agency. We combine engineering, design and AI to help businesses establish and grow their digital presence.","story":"Dev Creative Works began with a simple belief: every business deserves a digital presence that feels as ambitious as its ideas. What started as freelance web projects grew into a multidisciplinary studio delivering websites, AI automation, product design and brand identity for clients across industries.","mission":"To build digital products that are beautiful, fast and genuinely useful — and to make modern technology accessible to businesses of every size.","vision":"Empowering businesses with technology, creativity, and digital innovation.","approach":"We start with understanding, design with intent and build with care. Small, focused teams, transparent milestones and a bias for shipping work that moves the numbers."}'::jsonb),
('core_values', '[{"title":"Craft","description":"We sweat the details others skip."},{"title":"Clarity","description":"Simple communication, honest timelines, no jargon."},{"title":"Curiosity","description":"We keep learning so our clients stay ahead."},{"title":"Commitment","description":"We stay with you long after launch."}]'::jsonb),
